"""Parameterized cases aligned with 接口测试用例/01-用户模块用例.md."""

from __future__ import annotations


# 对应用例 USER-001 ~ USER-007
REGISTER_CASES = [
    {
        "id": "USER-001_register_success",
        "prepare_duplicate": False,
        "username": None,
        "password": "123456",
        "email": None,
        "missing_email": False,
        "only_required": False,
        "expected_success": True,
        "expected_message_contains": "成功",
    },
    {
        "id": "USER-002_register_duplicate_username",
        "prepare_duplicate": True,
        "username": None,
        "password": "123456",
        "email": None,
        "missing_email": False,
        "only_required": False,
        "expected_success": False,
        "expected_message_contains": "存在",
    },
    {
        "id": "USER-003_register_username_too_short",
        "prepare_duplicate": False,
        "username": "ab",
        "password": "123456",
        "email": None,
        "missing_email": False,
        "only_required": False,
        "expected_success": False,
        "expected_message_contains": "用户名长度必须在3-20之间",
    },
    {
        "id": "USER-004_register_username_too_long",
        "prepare_duplicate": False,
        "username": "a" * 21,
        "password": "123456",
        "email": None,
        "missing_email": False,
        "only_required": False,
        "expected_success": False,
        "expected_message_contains": "用户名长度必须在3-20之间",
    },
    {
        "id": "USER-005_register_password_too_short",
        "prepare_duplicate": False,
        "username": None,
        "password": "12345",
        "email": None,
        "missing_email": False,
        "only_required": False,
        "expected_success": False,
        "expected_message_contains": "密码长度必须在6-20之间",
    },
    {
        "id": "USER-006_register_missing_email",
        "prepare_duplicate": False,
        "username": None,
        "password": "123456",
        "email": None,
        "missing_email": True,
        "only_required": False,
        "expected_success": False,
        "expected_message_contains": "邮箱不能为空",
    },
    {
        "id": "USER-007_register_only_required_fields",
        "prepare_duplicate": False,
        "username": None,
        "password": "123456",
        "email": None,
        "missing_email": False,
        "only_required": True,
        "expected_success": True,
        "expected_message_contains": "成功",
    },
]


